    "error": {
      "$comment": "Typed Runtime validation additionally enforces the provider kind/status policy. Schema enforces exact outer/inner class and retryable equality.",
      "type": "object",
      "required": [
        "schema_version",
        "class",
        "retryable"
      ],
      "additionalProperties": false,
      "properties": {
        "schema_version": {
          "const": "runtime-error/0.1"
        },
        "class": {
          "$ref": "#/$defs/runtimeErrorClass"
        },
        "retryable": {
          "type": "boolean"
        },
        "provider_error": {
          "$ref": "#/$defs/providerError"
        }
      },
      "allOf": [
        {
          "if": {
            "required": [
              "provider_error"
            ]
          },
          "then": {
            "allOf": [
              {
                "oneOf": [
                  {
                    "properties": {
                      "class": {
                        "const": "provider"
                      },
                      "provider_error": {
                        "properties": {
                          "class": {
                            "const": "provider"
                          }
                        }
                      }
                    }
                  },
                  {
                    "properties": {
                      "class": {
                        "const": "transport"
                      },
                      "provider_error": {
                        "properties": {
                          "class": {
                            "const": "transport"
                          }
                        }
                      }
                    }
                  },
                  {
                    "properties": {
                      "class": {
                        "const": "timeout"
                      },
                      "provider_error": {
                        "properties": {
                          "class": {
                            "const": "timeout"
                          }
                        }
                      }
                    }
                  },
                  {
                    "properties": {
                      "class": {
                        "const": "sandbox"
                      },
                      "provider_error": {
                        "properties": {
                          "class": {
                            "const": "sandbox"
                          }
                        }
                      }
                    }
                  },
                  {
                    "properties": {
                      "class": {
                        "const": "policy"
                      },
                      "provider_error": {
                        "properties": {
                          "class": {
                            "const": "policy"
                          }
                        }
                      }
                    }
                  },
                  {
                    "properties": {
                      "class": {
                        "const": "budget"
                      },
                      "provider_error": {
                        "properties": {
                          "class": {
                            "const": "budget"
                          }
                        }
                      }
                    }
                  }
                ]
              },
              {
                "oneOf": [
                  {
                    "properties": {
                      "retryable": {
                        "const": true
                      },
                      "provider_error": {
                        "properties": {
                          "retryable": {
                            "const": true
                          }
                        }
                      }
                    }
                  },
                  {
                    "properties": {
                      "retryable": {
                        "const": false
                      },
                      "provider_error": {
                        "properties": {
                          "retryable": {
                            "const": false
                          }
                        }
                      }
                    }
                  }
                ]
              }
            ]
          }
        }
      ]
    },
