    "usageReasoningValue": {
      "type": "object",
      "required": [
        "kind",
        "available",
        "enabled",
        "output_tokens"
      ],
      "additionalProperties": false,
      "properties": {
        "kind": {
          "const": "reasoning"
        },
        "available": {
          "oneOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ]
        },
        "enabled": {
          "oneOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ]
        },
        "output_tokens": {
          "$ref": "#/$defs/nullableSafeInteger"
        }
      },
      "allOf": [
        {
          "anyOf": [
            {
              "properties": {
                "available": {
                  "type": "boolean"
                }
              }
            },
            {
              "properties": {
                "enabled": {
                  "type": "boolean"
                }
              }
            },
            {
              "properties": {
                "output_tokens": {
                  "$ref": "#/$defs/safeNonNegativeInteger"
                }
              }
            }
          ]
        },
        {
          "if": {
            "properties": {
              "available": {
                "const": false
              }
            }
          },
          "then": {
            "not": {
              "properties": {
                "enabled": {
                  "const": true
                }
              },
              "required": [
                "enabled"
              ]
            }
          }
        },
        {
          "if": {
            "properties": {
              "enabled": {
                "const": false
              }
            }
          },
          "then": {
            "properties": {
              "output_tokens": {
                "oneOf": [
                  {
                    "const": 0
                  },
                  {
                    "type": "null"
                  }
                ]
              }
            }
          }
        }
      ]
    },
